// Package: Microsoft.SemanticKernel, Microsoft.Extensions.AI, System.Text.Json

using Microsoft.SemanticKernel;
using Microsoft.Extensions.AI;
using System.Text.Json;
using System.ComponentModel;

public class AgentMessage
{
    public string Role { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public List<ToolCall>? ToolCalls { get; set; }
}

public class ToolCall
{
    public string Id { get; set; } = Guid.NewGuid().ToString();
    public string Name { get; set; } = string.Empty;
    public Dictionary<string, object?> Arguments { get; set; } = new();
}

public class ToolResult
{
    public string CallId { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public bool IsError { get; set; }
    public string? ErrorMessage { get; set; }
}

public class AgentState
{
    private readonly List<AgentMessage> _messages = new();
    private readonly Dictionary<string, ToolResult> _toolResults = new();
    private const int MaxToolCalls = 5;

    public int ToolCallCount { get; private set; }
    public IReadOnlyList<AgentMessage> Messages => _messages;
    public IReadOnlyDictionary<string, ToolResult> ToolResults => _toolResults;

    public void AddUserMessage(string content)
    {
        _messages.Add(new AgentMessage { Role = "user", Content = content });
    }

    public void AddAssistantMessage(string content, List<ToolCall>? toolCalls = null)
    {
        _messages.Add(new AgentMessage { Role = "assistant", Content = content, ToolCalls = toolCalls });
    }

    public void AddToolResult(ToolResult result)
    {
        _toolResults[result.CallId] = result;
        _messages.Add(new AgentMessage { Role = "tool", Content = result.Content });
        ToolCallCount++;
    }

    public bool CanMakeToolCall => ToolCallCount < MaxToolCalls;
}

public class ToolExecutor
{
    private readonly Kernel _kernel;

    public ToolExecutor(Kernel kernel)
    {
        _kernel = kernel;
    }

    public async Task<ToolResult> ExecuteAsync(FunctionToolCall call, CancellationToken ct = default)
    {
        try
        {
            var arguments = new KernelArguments();
            foreach (var arg in call.Arguments)
                arguments[arg.Key] = arg.Value?.ToString();

            var result = await _kernel.InvokeAsync(
                pluginName: call.Name.Split('.')[0],
                functionName: call.Name.Split('.')[1],
                arguments: arguments,
                cancellationToken: ct);

            return new ToolResult
            {
                CallId = call.CallId,
                Content = result.GetValue<string>() ?? string.Empty,
                IsError = false
            };
        }
        catch (Exception ex)
        {
            return new ToolResult
            {
                CallId = call.CallId,
                Content = string.Empty,
                IsError = true,
                ErrorMessage = $"Tool execution failed: {ex.Message}"
            };
        }
    }
}

public class AgentTurnRunner
{
    private readonly IChatClient _chatClient;
    private readonly ToolExecutor _toolExecutor;
    private readonly List<AIFunction> _toolDefinitions;

    public AgentTurnRunner(IChatClient chatClient, Kernel kernel)
    {
        _chatClient = chatClient;
        _toolExecutor = new ToolExecutor(kernel);
        _toolDefinitions = kernel.GetServices<AIFunction>().ToList();
    }

    public async Task<AgentTurn> RunTurnAsync(AgentState state, CancellationToken ct = default)
    {
        if (!state.CanMakeToolCall)
        {
            return new AgentTurn { FinalMessage = "Maximum tool calls reached." };
        }

        var response = await _chatClient.GetResponseAsync(
            state.Messages,
            tools: _toolDefinitions,
            cancellationToken: ct);

        var toolCalls = response.FinishReason == FinishReason.ToolCalls
            ? response.ToolCalls.ToList()
            : new List<FunctionToolCall>();

        foreach (var call in toolCalls)
        {
            var result = await _toolExecutor.ExecuteAsync(call, ct);
            state.AddToolResult(result);
        }

        return new AgentTurn
        {
            Response = response,
            ToolCalls = toolCalls,
            FinalMessage = toolCalls.Count == 0 ? response.Text : null
        };
    }
}

public class AgentTurn
{
    public object? Response { get; set; }
    public List<FunctionToolCall> ToolCalls { get; set; } = new();
    public string? FinalMessage { get; set; }
}

